import { parse } from 'date-fns';
import { WalletNewList } from '~/entities/wallet/api/dtos/wallet-history-list';
import { WalletItemDTO } from '~/entities/wallet/api/dtos/wallet-item';
import { formatDate } from './format-date';
import { formatDay } from './format-day';
import { formatTime } from './format-time';
import { generateTitle } from './generate-title';

export const restructureList = (list: WalletItemDTO[]) => {
  const newList: WalletNewList = {};
  list.map((item) => {
    // 상태값에 따라 타이틀명 생성
    item.title = generateTitle(item);

    const date = parse(item?.trnscDcsnDt, 'yyyy-MM-dd HH:mm:ss', new Date());
    item.date = formatDate(date);
    item.time = formatTime(date);
    // 날짜별로 묶기
    const day = formatDay(date);
    if (!newList[day]) {
      newList[day] = [];
    }
    newList[day].push(item);
  });
  return newList;
};
